---@class UITeamMemberNode
---@field Env                           	UITeamMemberNode              
---@field controller                    	Engine.Modules.LuaBehaviour                   
---@field CardPar                       	UnityEngine.RectTransform                            
local UITeamMemberNode = Class("UITeamMemberNode")
function UITeamMemberNode:__init() 
    self._data = nil
    self._scale = 1
    self._cardCb = nil
    self.isIgnoreCardSize = false
end

function UITeamMemberNode:__delete()
    self._data = nil
    self._scale = 1
    self._cardCb = nil
    self.isIgnoreCardSize = false
end

function UITeamMemberNode:Awake()
    self.cardTrans  = self.CardPar.transform:Find("card")
    self.PatrolRole = self.controller.transform:Find("StatusNode/PatrolRole")
    self.ImgSelect  = self.controller.transform:Find("StatusNode/ImgSelect")
end

function UITeamMemberNode:Start()
end

function UITeamMemberNode:Refresh(data, scale, cardCb, upBuffData)
    self._data = data
    if scale then
        self._scale = scale
    end
    self._cardCb = cardCb
    self._upBuffData = upBuffData

    if self._data and (checkNumber(self._data.id) ~= 0 or checkNumber(self._data.cardId) ~=0) then
        self:FillMemberData()
    else
        --绘制空的数据
        self:FillEmptyData()
    end

    self.controller.gameObject.transform.localScale = Vector3(self._scale, self._scale, 1)
    KTool.SetActive(self.controller.gameObject, true)

    self:FillUpInfo()

    local go = self.cardTrans
    return go
end

--绘制up图片
function UITeamMemberNode:FillUpInfo(isUp)
    if self._data and self._upBuffData then
        isUp = QuestConfMgr:GetInstance():IsCardUp(self._data.cardId, self._upBuffData)
    end

    ---@type CardHeadNode
    local scr = self:GetCardHeadNodeEnv()
    if isNotNull(scr) then
        scr:FillUpInfo(isUp)
    end
end

function UITeamMemberNode:FillEmptyData()
    KTool.SetActive(self.CardPar, false)
    SetButtonAction(self.MemberBg, function()
        if self._cardCb then
            self._cardCb()
        end
    end)
end

function UITeamMemberNode:SetClickCb(callback)
    self._cardCb = callback
end

function UITeamMemberNode:FillMemberData()
    KTool.SetActive(self.CardPar, true)
    local go = self.cardTrans
    if not go then
        if IsNull(self.loader) then
            self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
        end
        if self.loader.IsSuccess then
            go = CfUtils.InstantiateGo(self.loader.ResultObject, self.CardPar)
            KTool.SetActive(go, true)
            go.name = "card"
        end
        if go then
            go.transform.localPosition = Vector3(0, 0, 0)
        end
    end
    if go then
        local localScale = self.isIgnoreCardSize and go.transform.localScale or Vector3(1, 1, 1)
        CfUtils.RefeshCommonSmallHeroGo(go, self._data, localScale, function()
            if self._cardCb then
                self._cardCb(self._data.id)
            end
        end)
    end

    self:FillRobot()
end

----只绘制卡牌头像
function UITeamMemberNode:FillCardBase(data, scale, cardCb, exArgs)
    self._cardCb = cardCb
    local go = self.cardTrans
    if not go then
        if IsNull(self.loader) then
            self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
        end
        if self.loader.IsSuccess then
            go = CfUtils.InstantiateGo(self.loader.ResultObject, self.CardPar)
            go.name = "card"
        end
        if go then
            go.transform.localPosition = Vector3(0, 0, 0)
        end
    end

    if scale then
        go.transform.localScale = Vector3(scale, scale, 1)
    end
    local scr = self:GetCardHeadNodeEnv()
    if scr then
        local exArgs = checkTable(exArgs)
        if not data.cardId then
            data.cardId = data.refId
        end
        scr:FreshNode(data)
        scr:SetCallBack(function()
            if self._cardCb then
                self._cardCb()
            end
        end)

        scr:SetLvStatus(false)
        scr:SetStarStatus(false)
        scr:SetBottomImageStatus(false)
        if exArgs.showStar then
            scr:SetStarStatus(true)
        end
    end
    KTool.SetActive(self.MemberBg, false)
    KTool.SetActive(self.controller.gameObject, true)

    return go
end

----绘制猫屋训练
function UITeamMemberNode:FillCardCatTrain(data, scale, cardCb)
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local isHaveCard = cardComponent:IsHasCard(data.refId)
    local haveCardData
    if isHaveCard then
        haveCardData = cardComponent:GetCardById(cardComponent:GetIdByCardId(data.refId))
    end

    self._cardCb = cardCb
    local go = self.cardTrans
    if not go then
        if IsNull(self.loader) then
            self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
        end
        if self.loader.IsSuccess then
            go = CfUtils.InstantiateGo(self.loader.ResultObject, self.CardPar)
            go.name = "card"
        end
        if go then
            go.transform.localPosition = Vector3(0, 0, 0)
        end
    end

    if scale then
        go.transform.localScale = Vector3(scale, scale, 1)
    end
    

    local scr = self:GetCardHeadNodeEnv()
    if scr then
        if not data.cardId then
            data.cardId = data.refId
        end
        if not isHaveCard then
            scr:FreshNode(data)
        else
            scr:FreshNode(haveCardData, true)
        end
        scr:SetCallBack(function()
            if self._cardCb then
                self._cardCb()
            end
        end)

        --scr:SetLvStatus(false)
        --scr:SetStarStatus(false)
        scr:SetAttrGroupStatus(false)
        scr:SetCareerStatus(false)
        --scr:SetBottomImageStatus(false)
    end
    KTool.SetActive(self.MemberBg, false)
    KTool.SetActive(self.controller.gameObject, true)
end

----怪物头像
function UITeamMemberNode:FillMonster(data, scale, cardCb)
    self:FillBase(data, scale, cardCb)
    
    local scr = self:GetCardHeadNodeEnv()
    if scr then
        local monsterTypeData = CfUtils.GetCfVo(AutoIds.IdSetting39, "MonsterTypeVo", data.id)
        if isNull(monsterTypeData) then
            scr:FreshNode(data)
            scr:SetLvStatus(true)
        else
            scr:FreshMonsterUI(monsterTypeData, data.rare,nil,data.attribute)
            scr:SetStarStatus(false)
            scr:SetBottomImageStatus(false)
            if data.hpPercent == nil then
                self:ShowHpEnergy(false)
            else
                self:FillHpEnergy(data, scale)
            end
        end
    end
end

