----绘制夜巡战斗事件的角色预览头像（无等级）
function UITeamMemberNode:FillCardPatrol(data, scale, cardCb)
    self._cardCb = cardCb
    local go = self.cardTrans
    if not go then
        if IsNull(self.loader) then
            self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/CommonSmallHeadNode.prefab", nil, true)
        end
        if self.loader.IsSuccess then
            go = CfUtils.InstantiateGo(self.loader.ResultObject, self.CardPar)
            go.name = "card"
        end
        if go then
            go.transform.localPosition = Vector3(0, 0, 0)
        end
    end

    if scale then
        go.transform.localScale = Vector3(scale, scale, 1)
    end
    local scr = self:GetCardHeadNodeEnv()
    if scr then
        local idType = checkInt(data.idType)
        if idType == Constants.IDType.QuestPatrolMaze then
            local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
            local assistCardDojo  = PatrolMazeUtils.GetAssistCardDojo(data.id)
            scr:FreshNode(assistCardDojo)
            scr:SetLvStatus(true)
            CfUtils.SetActive(self.PatrolRole, true)
        else
            local monsterTypeData = CfUtils.GetCfVo(AutoIds.IdSetting39, "MonsterTypeVo", data.id)
            if isNull(monsterTypeData) then--助战
                scr:FreshNode(data)
                scr:SetLvStatus(true)
            else
                scr:FreshMonsterUI(monsterTypeData, data.rare)
                scr:SetStarStatus(false)
                scr:SetBottomImageStatus(false)
                self:FillHpEnergy(data, scale)
            end
        end
        scr:SetCallBack(function()
            if self._cardCb then
                self._cardCb()
            end
        end)
    end
    KTool.SetActive(self.MemberBg, false)
    KTool.SetActive(self.controller.gameObject, true)
end

function UITeamMemberNode:ShowHpEnergy(isShow)
    CfUtils.SetActive(self.HpEnergy, isShow)
end
function UITeamMemberNode:FillHpEnergy(hpEnergyData, maxEnergyNum)
    self:ShowHpEnergy(true)
    ---@type UICommonHpAndEnergyNode
    local uiCommonHpAndEnergyNodeScr = CfUtils.GetLuaScr(self.HpEnergy, UICommonHpAndEnergyNode)
    if uiCommonHpAndEnergyNodeScr then
        uiCommonHpAndEnergyNodeScr:RefreshCardHpEnergy(hpEnergyData, maxEnergyNum)
    end
end

function UITeamMemberNode:FillBg(isLimit)
    CfUtils.SetActive(self.MemberBg, true)
    if isLimit then
        CfUtils.SetActive(self.controller.gameObject.transform:Find("ImgBg"), true)
        CfUtils.FillImage(self.MemberBg, "UIAtlas/Common/group_bg_ban.png")
        self._cardCb = nil
    else
        CfUtils.FillImage(self.MemberBg, "UIAtlas/Common/group_bg_add.png")
    end
end

function UITeamMemberNode:FillLocked(isLocked)
    local scr = self:GetCardHeadNodeEnv()
    if not scr then
        return
    end

    scr:SetLockStatus(isLocked)
end

--绘制机器人
function UITeamMemberNode:FillRobot()
    local scr = self:GetCardHeadNodeEnv()
    if not scr then
        return
    end

    local isShow = true
    --没数据
    if self._data then
        isShow = checkNumber(self._data.isAssistant) ~= Constants.MazeRole.AssistRole
    end

    scr:SetBottomImageStatus(isShow)
    scr:SetLvStatus(isShow)
    scr:SetStarStatus(isShow)
end

