---GetCardHeadNodeEnv
---@return CardHeadNode
function UITeamMemberNode:GetCardHeadNodeEnv()
    if isNull(self.cardTrans) then
        -- 异步PVP快速战斗里面的card是动态加载出来，awake的时候是获取不到的，这里再获取一次
        self.cardTrans = self.CardPar.transform:Find("card")
    end
    if isNull(self._cardHeadEnv) then
        self._cardHeadEnv = CfUtils.GetLuaScr(self.cardTrans, "Game.Behaviours.CardHeadNode")
    end
    return self._cardHeadEnv
end

function UITeamMemberNode:OnDestroy()
    if not isNull(self.loader) then
        self.loader:Release(true)
        self.loader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UITeamMemberNode
